// Probability of the positive class for a feature vector from crash_features().
static inline float crash_model_probability(const float *x) {
  float raw = CRASH_MODEL_BIAS[0];
  for (int t = 0; t < CRASH_MODEL_N_TREES; t++) {
    uint32_t i = CRASH_MODEL_ROOT[t];
    while (CRASH_MODEL_FEAT[i] >= 0) i = (x[CRASH_MODEL_FEAT[i]] <= CRASH_MODEL_THR[i]) ? i + 1 : CRASH_MODEL_NO[i];
    raw += CRASH_MODEL_THR[i];
  }
  return 1.0f / (1.0f + expf(-raw));
}
